// X15: one SVG token keeps its identity through document -> baton -> document.
{
  const a=at('X15',0), b=at('X15',1), c=at('X15',2);
  tl.from('#s15 #token15,#s15 #sender15body,#s15 #identity15',{opacity:0,y:16,duration:.35,ease:'power2.out'},a+.06);
  tl.to('#s15 #sender15body',{opacity:0,duration:.2},b);
  tl.to('#s15 #token15',{attr:{x:742,y:510,width:438,height:66,rx:33},duration:.55,ease:'power3.inOut'},b+.05);
  tl.to('#s15 #identity15',{attr:{x:850,y:552},duration:.55,ease:'power3.inOut'},b+.05);
  tl.to('#s15 #actor15a',{opacity:.4,duration:.4},b+.28);
  tl.to('#s15 #token15',{attr:{x:1040},duration:.45,ease:'sine.inOut'},b+.62);
  tl.to('#s15 #identity15',{attr:{x:1148},duration:.45,ease:'sine.inOut'},b+.62);
  tl.to('#s15 #token15',{attr:{x:1295,y:351,width:330,height:360,rx:26},duration:.44,ease:'power3.inOut'},c+.02);
  tl.to('#s15 #identity15',{attr:{x:1330,y:400},duration:.44,ease:'power3.inOut'},c+.02);
  tl.to('#s15 #receiver15outline',{opacity:0,duration:.22},c+.35);
  tl.to('#s15 #receiver15body',{opacity:1,duration:.24},c+.34);
  tl.to('#s15 #actor15b circle',{attr:{fill:'#101112'},duration:.25},c+.3);
  tl.to('#s15 #actor15b .actor',{attr:{fill:'#cdb7f5'},duration:.25},c+.3);
  tl.to('#s15 .handoff-note',{opacity:1,y:-8,duration:.2,ease:'power2.out'},c+.4);
}
// X16: counted units, explicitly a process example. No unsupported performance claim.
{
  const a=at('X16',0), b=at('X16',1), c=at('X16',2);
  tl.from('#s16 .unit',{opacity:0,y:25,stagger:.045,duration:.3,ease:'power2.out'},a+.06);
  tl.from('#s16 #measure16',{opacity:0,duration:.3},a+.32);
  tl.to('#s16 #count16old',{opacity:0,y:-14,duration:.23},b);
  tl.to('#s16 #count16new',{opacity:1,duration:.3},b+.14);
  for(let i=4;i<=10;i++){
    const currentX=230+(i-1)*148;
    tl.to('#s16 #unit16'+i,{x:652-currentX,scaleX:0,opacity:0,duration:.62,ease:'power3.inOut'},b+.05+(10-i)*.025);
  }
  tl.to('#s16 #measure16',{attr:{d:'M230 660 V687 H652 V660'},duration:.72,ease:'power3.inOut'},b+.05);
  tl.to('#s16 #measure16old',{opacity:0,duration:.2},b+.05);
  tl.to('#s16 #measure16new',{opacity:1,duration:.3},b+.59);
  tl.to('#s16 .legend span+span',{opacity:.4,duration:.3},b+.65);
  tl.to('#s16 .result',{opacity:1,y:-10,duration:.45,ease:'power2.out'},c+.12);
}
// X17: later steps are put away in a temporal group, then only one is reopened.
{
  const a=at('X17',0), b=at('X17',1), c=at('X17',2);
  tl.from('#s17 #current17',{scale:.94,opacity:0,duration:.36,ease:'power3.out'},a+.06);
  tl.from('#s17 .work-card:not(#current17)',{opacity:.2,y:18,stagger:.08,duration:.4},a+.1);
  tl.to('#s17 .later-label',{opacity:0,duration:.2},b);
  tl.to('#s17 .work-card:not(#current17) > *',{autoAlpha:0,duration:.16},b-.02);
  tl.to('#s17 .folder',{opacity:1,duration:.4},b+.1);
  tl.to('#s17 #later17a',{x:405,y:-2,scale:.73,duration:.62,ease:'power3.inOut'},b+.02);
  tl.to('#s17 #later17b',{x:57,y:23,scale:.73,duration:.62,ease:'power3.inOut'},b+.08);
  tl.to('#s17 #later17c',{x:-291,y:48,scale:.73,duration:.62,ease:'power3.inOut'},b+.14);
  tl.to('#s17 #later17a p,#s17 #later17b p,#s17 #later17c p',{opacity:0,duration:.25},b+.12);
  tl.to('#s17 #later17a',{x:380,y:-25,scale:1,duration:.48,ease:'power3.inOut'},c+.02);
  tl.to('#s17 #later17a > *',{autoAlpha:1,duration:.22},c+.22);
  tl.to('#s17 #later17b',{x:328,y:1,scale:.67,duration:.48,ease:'power3.inOut'},c+.02);
  tl.to('#s17 #later17c',{x:-34,y:26,scale:.67,duration:.48,ease:'power3.inOut'},c+.02);
  tl.to('#s17 .fold-note',{opacity:1,y:-5,duration:.22},c+.36);
}
// X18: a footnote anchors one claim to one sentence in clearly marked sample text.
{
  const a=at('X18',0), b=at('X18',1), c=at('X18',2);
  tl.from('#s18 .claim',{opacity:0,y:17,duration:.35,ease:'power2.out'},a+.08);
  tl.from('#s18 .source',{opacity:.3,duration:.4},a+.14);
  tl.from('#s18 .footnote',{scale:.65,opacity:0,duration:.3,ease:'power2.out'},b+.03);
  tl.from('#s18 #evidence18path',{strokeDasharray:350,strokeDashoffset:350,duration:.65,ease:'power2.out'},b+.14);
  tl.to('#s18 .connection-label',{opacity:1,duration:.3},b+.22);
  tl.to('#s18 .locator',{opacity:1,scale:1.05,duration:.27,ease:'power2.out'},c+.03);
  tl.from('#s18 .mark',{scaleX:0,duration:.48,ease:'power2.inOut'},c+.08);
  tl.to('#s18 .source-line.other',{opacity:.45,duration:.35},c+.18);
}
// X19: the same question object becomes a bookmark, then returns above its answer.
{
  const a=at('X19',0), b=at('X19',1), c=at('X19',2);
  tl.to('#s19 .bookmark',{x:910,y:-37,scale:.41,duration:.48,ease:'power3.inOut'},a+.14);
  tl.to('#s19 .bookmark-caption',{opacity:1,duration:.23},a+.49);
  tl.to('#s19 .example',{opacity:1,y:-12,duration:.35,ease:'power2.out'},a+.6);
  tl.to('#s19 .example',{opacity:0,y:12,duration:.25},b+.02);
  tl.to('#s19 .bookmark-caption',{opacity:0,duration:.2},b+.02);
  tl.to('#s19 .bookmark',{x:-90,y:-1,scale:1.1875,duration:.58,ease:'power3.inOut'},b+.08);
  tl.to('#s19 .answer',{opacity:1,y:-9,duration:.42,ease:'power2.out'},c+.05);
  tl.from('#s19 .answer-rule',{scaleX:0,duration:.36,ease:'power2.out'},c+.22);
}
// X20: the concept groups converge into a sentence structure, then leave one line.
{
  const a=at('X20',0), b=at('X20',1), c=at('X20',2);
  tl.from('#s20 .concept',{opacity:0,y:25,stagger:.09,duration:.35,ease:'power2.out'},a+.05);
  tl.to('#s20 .concept-bg,#s20 .concept-id,#s20 .concept-guide,#s20 .join-symbol',{opacity:0,duration:.28},b+.02);
  tl.to('#s20 #concept20a',{x:280,y:127,duration:.64,ease:'power3.inOut'},b+.08);
  tl.to('#s20 #concept20b',{x:33,y:127,duration:.64,ease:'power3.inOut'},b+.08);
  tl.to('#s20 #concept20c',{x:-310,y:127,duration:.64,ease:'power3.inOut'},b+.08);
  tl.to('#s20 .concept-key',{x:-33,y:-141,scale:.455882353,color:'#a59baa',duration:.64,ease:'power3.inOut'},b+.08);
  tl.to('#s20 .final-piece',{opacity:1,duration:.35},c+.06);
  tl.to('#s20 .concept-key',{opacity:0,y:-151,duration:.3},c+.18);
  tl.to('#s20 .conclusion-label',{opacity:1,duration:.4},c+.14);
  tl.fromTo('#s20 .assembly-line',{scaleX:0,opacity:0},{scaleX:1,opacity:1,duration:.4,ease:'power2.out'},c+.2);
}
